import unittest
from decimal import Decimal

from src.api.partner_adapter import to_partner_payload


def order(amount_cents: int, partner_id: str = "p-1") -> dict:
    return {
        "id": "o-1",
        "partner_id": partner_id,
        "amount_cents": amount_cents,
        "created_at": "2026-01-01",
    }


class PartnerAdapterCase(unittest.TestCase):
    def test_payload_carries_the_order_identifier(self):
        self.assertEqual(to_partner_payload(order(500))["orderId"], "o-1")

    def test_amount_is_converted_to_fractional_units(self):
        self.assertEqual(to_partner_payload(order(549))["amount"], Decimal("5.49"))
        self.assertEqual(to_partner_payload(order(550))["amount"], Decimal("5.50"))

    def test_every_partner_receives_fractional_amounts(self):
        self.assertEqual(to_partner_payload(order(549, "p-9"))["amount"], Decimal("5.49"))
        self.assertEqual(to_partner_payload(order(100, "p-7"))["amount"], Decimal("1.00"))
